create table destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22 (
 roadmap_key text primary key,
 version integer not null check(version>0),
 title text not null,
 source_git_repository text not null,
 source_git_path text not null,
 source_git_commit text not null check(source_git_commit~'^[0-9a-f]{40}$'),
 canonical_digest text,
 sealed boolean not null default false,
 is_active boolean not null default false,
 created_at timestamptz not null default now(),
 metadata jsonb not null default '{}'::jsonb,
 check(not sealed or canonical_digest~'^[0-9a-f]{64}$')
);
create unique index compute_fabric_canonical_roadmap_one_active_h205f22 on destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22((1)) where is_active;

create table destruktion_meta.compute_fabric_canonical_milestone_h205f22 (
 roadmap_key text not null references destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22(roadmap_key) on delete restrict,
 canonical_milestone_key text not null,
 ordinal integer not null check(ordinal>0),
 title text not null,
 historical_source text not null,
 objective text not null,
 acceptance_criteria jsonb not null check(jsonb_typeof(acceptance_criteria)='array' and jsonb_array_length(acceptance_criteria)>0),
 critical_path boolean not null default false,
 parallel_track boolean not null default false,
 sealed boolean not null default false,
 created_at timestamptz not null default now(),
 primary key(roadmap_key,canonical_milestone_key),
 unique(roadmap_key,ordinal)
);

create table destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22 (
 roadmap_id text not null,
 milestone_key text not null,
 canonical_roadmap_key text not null references destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22(roadmap_key) on delete restrict,
 canonical_milestone_key text,
 mapping_kind text not null check(mapping_kind in('PRIMARY','SUBMILESTONE','ACCEPTANCE_GATE','CROSS_CUTTING')),
 required_contribution text not null,
 acceptance_bridge jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now(),
 primary key(roadmap_id,milestone_key,canonical_roadmap_key),
 foreign key(roadmap_id,milestone_key) references destruktion_meta.compute_fabric_roadmap_milestone_h205f22(roadmap_id,milestone_key) on delete restrict,
 foreign key(canonical_roadmap_key,canonical_milestone_key) references destruktion_meta.compute_fabric_canonical_milestone_h205f22(roadmap_key,canonical_milestone_key) on delete restrict,
 check((mapping_kind='CROSS_CUTTING' and canonical_milestone_key is null) or (mapping_kind<>'CROSS_CUTTING' and canonical_milestone_key is not null))
);
create index compute_fabric_level2_canonical_mapping_l1_h205f22 on destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22(canonical_roadmap_key,canonical_milestone_key);

create table destruktion_meta.compute_fabric_canonical_roadmap_dependency_h205f22 (
 roadmap_key text not null references destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22(roadmap_key) on delete restrict,
 predecessor text not null,
 successor text not null,
 dependency_kind text not null check(dependency_kind in('ARCHITECTURAL_SPINE','PARALLEL_FOUNDATION','PRODUCTION_CONTINUITY')),
 rationale text not null,
 created_at timestamptz not null default now(),
 primary key(roadmap_key,predecessor,successor),
 foreign key(roadmap_key,predecessor) references destruktion_meta.compute_fabric_canonical_milestone_h205f22(roadmap_key,canonical_milestone_key) on delete restrict,
 foreign key(roadmap_key,successor) references destruktion_meta.compute_fabric_canonical_milestone_h205f22(roadmap_key,canonical_milestone_key) on delete restrict,
 check(predecessor<>successor)
);
create index compute_fabric_canonical_roadmap_dependency_successor_h205f22 on destruktion_meta.compute_fabric_canonical_roadmap_dependency_h205f22(roadmap_key,successor);

create table destruktion_meta.compute_fabric_canonical_progress_receipt_h205f22 (
 canonical_progress_receipt_id bigint generated always as identity primary key,
 step_receipt_id bigint not null unique references destruktion_meta.compute_fabric_roadmap_step_receipt_h205f22(receipt_id) on delete restrict,
 canonical_roadmap_key text not null references destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22(roadmap_key) on delete restrict,
 canonical_milestone_key text,
 canonical_acceptance_criterion text not null check(btrim(canonical_acceptance_criterion)<>''),
 canonical_progress_summary text not null check(btrim(canonical_progress_summary)<>''),
 real_compute_effect text not null check(btrim(real_compute_effect)<>''),
 control_plane_only boolean not null default false,
 control_plane_justification text,
 evidence jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now(),
 foreign key(canonical_roadmap_key,canonical_milestone_key) references destruktion_meta.compute_fabric_canonical_milestone_h205f22(roadmap_key,canonical_milestone_key) on delete restrict,
 check(not control_plane_only or nullif(btrim(control_plane_justification),'') is not null)
);
create index compute_fabric_canonical_progress_owner_h205f22 on destruktion_meta.compute_fabric_canonical_progress_receipt_h205f22(canonical_roadmap_key,canonical_milestone_key,created_at);

