create or replace function destruktion_meta.compute_fabric_canonical_release_guard_h205f22() returns trigger language plpgsql set search_path='pg_catalog','destruktion_meta' as $f$ begin if old.sealed then if tg_op='DELETE' then raise exception 'sealed canonical roadmap release cannot be deleted'; end if; if (to_jsonb(new)-'is_active')<>(to_jsonb(old)-'is_active') then raise exception 'sealed canonical roadmap release definition is immutable; create a new version'; end if; end if; if tg_op='DELETE' then return old; end if; return new; end $f$;
create or replace function destruktion_meta.compute_fabric_canonical_definition_guard_h205f22() returns trigger language plpgsql set search_path='pg_catalog','destruktion_meta' as $f$ declare k text; rs boolean; row_sealed boolean:=false; begin k:=coalesce(to_jsonb(new)->>tg_argv[0],to_jsonb(old)->>tg_argv[0]); select sealed into rs from destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22 where roadmap_key=k; if tg_op<>'INSERT' then row_sealed:=coalesce((to_jsonb(old)->>'sealed')::boolean,false); end if; if coalesce(rs,false) or row_sealed then raise exception 'sealed canonical Level-1 definition is immutable; create a new roadmap version'; end if; if tg_op='DELETE' then return old; end if; return new; end $f$;
create or replace function destruktion_meta.compute_fabric_canonical_progress_append_only_h205f22() returns trigger language plpgsql set search_path='pg_catalog','destruktion_meta' as $f$ begin raise exception 'canonical progress receipts are append-only'; end $f$;
create trigger compute_fabric_canonical_release_guard_h205f22 before update or delete on destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22 for each row execute function destruktion_meta.compute_fabric_canonical_release_guard_h205f22();
create trigger compute_fabric_canonical_milestone_guard_h205f22 before insert or update or delete on destruktion_meta.compute_fabric_canonical_milestone_h205f22 for each row execute function destruktion_meta.compute_fabric_canonical_definition_guard_h205f22('roadmap_key');
create trigger compute_fabric_canonical_mapping_guard_h205f22 before insert or update or delete on destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22 for each row execute function destruktion_meta.compute_fabric_canonical_definition_guard_h205f22('canonical_roadmap_key');
create trigger compute_fabric_canonical_dependency_guard_h205f22 before insert or update or delete on destruktion_meta.compute_fabric_canonical_roadmap_dependency_h205f22 for each row execute function destruktion_meta.compute_fabric_canonical_definition_guard_h205f22('roadmap_key');
create trigger compute_fabric_canonical_progress_append_only_h205f22 before update or delete on destruktion_meta.compute_fabric_canonical_progress_receipt_h205f22 for each row execute function destruktion_meta.compute_fabric_canonical_progress_append_only_h205f22();

