create or replace function destruktion_meta.compute_fabric_canonical_roadmap_digest_h205f22(p_roadmap_key text default null) returns text language plpgsql stable set search_path='pg_catalog','destruktion_meta','extensions' as $f$ declare k text; p jsonb; c text; begin if p_roadmap_key is null then select roadmap_key into k from destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22 where is_active order by version desc limit 1; else k:=p_roadmap_key; end if; if k is null then raise exception 'no active canonical roadmap'; end if; select jsonb_build_object('roadmap_key',r.roadmap_key,'version',r.version::text,'title',r.title,'milestones',coalesce((select jsonb_agg(jsonb_build_object('key',m.canonical_milestone_key,'ordinal',m.ordinal::text,'title',m.title,'historical_source',m.historical_source,'objective',m.objective,'acceptance_criteria',m.acceptance_criteria,'critical_path',m.critical_path,'parallel_track',m.parallel_track) order by m.ordinal) from destruktion_meta.compute_fabric_canonical_milestone_h205f22 m where m.roadmap_key=r.roadmap_key),'[]'::jsonb),'dependencies',coalesce((select jsonb_agg(jsonb_build_object('predecessor',d.predecessor,'successor',d.successor,'dependency_kind',d.dependency_kind,'rationale',d.rationale) order by d.predecessor collate "C",d.successor collate "C") from destruktion_meta.compute_fabric_canonical_roadmap_dependency_h205f22 d where d.roadmap_key=r.roadmap_key),'[]'::jsonb)) into p from destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22 r where r.roadmap_key=k; if p is null then raise exception 'unknown canonical roadmap %',k; end if; c:=destruktion_meta.compute_fabric_canonical_json_h205f22(p); return encode(extensions.digest(convert_to(c,'UTF8'),'sha256'),'hex'); end $f$;

create or replace function destruktion_meta.compute_fabric_canonical_claim_gate_h205f22(p_roadmap_id text,p_milestone_key text) returns jsonb language plpgsql stable set search_path='pg_catalog','destruktion_meta','extensions' as $f$ declare r record; m record; d text; begin select * into r from destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22 where is_active order by version desc limit 1; if not found then return jsonb_build_object('allowed',false,'reason','NO_ACTIVE_CANONICAL_ROADMAP'); end if; d:=destruktion_meta.compute_fabric_canonical_roadmap_digest_h205f22(r.roadmap_key); if not r.sealed or r.canonical_digest is distinct from d then return jsonb_build_object('allowed',false,'reason','CANONICAL_INTEGRITY_FAILED','canonical_roadmap_key',r.roadmap_key); end if; select * into m from destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22 where roadmap_id=p_roadmap_id and milestone_key=p_milestone_key and canonical_roadmap_key=r.roadmap_key; if not found then return jsonb_build_object('allowed',false,'reason','UNMAPPED_LEVEL2_MILESTONE','canonical_roadmap_key',r.roadmap_key); end if; return jsonb_build_object('allowed',true,'canonical_roadmap_key',r.roadmap_key,'canonical_digest',d,'canonical_milestone_key',m.canonical_milestone_key,'mapping_kind',m.mapping_kind,'required_contribution',m.required_contribution,'acceptance_bridge',m.acceptance_bridge); end $f$;

create or replace function destruktion_meta.compute_fabric_roadmap_alignment_status_h205f22() returns jsonb language plpgsql stable set search_path='pg_catalog','destruktion_meta','extensions' as $f$ declare r record; l2 jsonb; d text; ci boolean; li boolean; u jsonb; inv jsonb; ac jsonb; er jsonb; spine jsonb; focus jsonb; reasons text[]:='{}'; ab boolean; eb boolean; pb boolean; begin select * into r from destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22 where is_active order by version desc limit 1; if not found then return jsonb_build_object('schema','metaengine.compute.roadmap-alignment.h205f22.v1','canonical_integrity',false,'drift_detected',true,'drift_reasons',jsonb_build_array('NO_ACTIVE_CANONICAL_ROADMAP')); end if; d:=destruktion_meta.compute_fabric_canonical_roadmap_digest_h205f22(r.roadmap_key); ci:=r.sealed and r.canonical_digest=d; l2:=destruktion_meta.compute_fabric_roadmap_status_h205f22(); li:=coalesce((l2->>'definition_integrity')::boolean,false); select coalesce(jsonb_agg(m.milestone_key order by m.phase_order,m.priority,m.milestone_key),'[]') into u from destruktion_meta.compute_fabric_roadmap_milestone_h205f22 m left join destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22 x on x.roadmap_id=m.roadmap_id and x.milestone_key=m.milestone_key and x.canonical_roadmap_key=r.roadmap_key where m.roadmap_id=l2->>'roadmap_id' and x.milestone_key is null; select coalesce(jsonb_agg(jsonb_build_object('milestone_key',x.milestone_key,'mapping_kind',x.mapping_kind,'canonical_milestone_key',x.canonical_milestone_key) order by x.milestone_key),'[]') into inv from destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22 x left join destruktion_meta.compute_fabric_canonical_milestone_h205f22 cm on cm.roadmap_key=x.canonical_roadmap_key and cm.canonical_milestone_key=x.canonical_milestone_key where x.roadmap_id=l2->>'roadmap_id' and x.canonical_roadmap_key=r.roadmap_key and((x.mapping_kind='CROSS_CUTTING' and x.canonical_milestone_key is not null)or(x.mapping_kind<>'CROSS_CUTTING' and cm.canonical_milestone_key is null)); select coalesce(jsonb_agg(jsonb_build_object('claim_id',c.claim_id,'milestone_key',c.milestone_key,'canonical_milestone_key',x.canonical_milestone_key,'mapping_kind',x.mapping_kind,'aligned',(x.milestone_key is not null and ci)) order by c.claim_id),'[]'),coalesce(bool_or(x.milestone_key is null),false) into ac,ab from destruktion_meta.compute_fabric_roadmap_work_claim_h205f22 c left join destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22 x on x.roadmap_id=c.roadmap_id and x.milestone_key=c.milestone_key and x.canonical_roadmap_key=r.roadmap_key where c.state='ACTIVE' and c.roadmap_id=l2->>'roadmap_id'; select coalesce(jsonb_agg(jsonb_build_object('claim_id',c.claim_id,'milestone_key',c.milestone_key,'canonical_milestone_key',x.canonical_milestone_key,'mapping_kind',x.mapping_kind,'progress_receipt_present',exists(select 1 from destruktion_meta.compute_fabric_roadmap_step_receipt_h205f22 sr join destruktion_meta.compute_fabric_canonical_progress_receipt_h205f22 pr on pr.step_receipt_id=sr.receipt_id where sr.claim_id=c.claim_id and pr.canonical_roadmap_key=r.roadmap_key and pr.canonical_milestone_key is not distinct from x.canonical_milestone_key),'aligned',(x.milestone_key is not null and exists(select 1 from destruktion_meta.compute_fabric_roadmap_step_receipt_h205f22 sr join destruktion_meta.compute_fabric_canonical_progress_receipt_h205f22 pr on pr.step_receipt_id=sr.receipt_id where sr.claim_id=c.claim_id and pr.canonical_roadmap_key=r.roadmap_key and pr.canonical_milestone_key is not distinct from x.canonical_milestone_key))) order by c.claim_id),'[]'),coalesce(bool_or(x.milestone_key is null or not exists(select 1 from destruktion_meta.compute_fabric_roadmap_step_receipt_h205f22 sr join destruktion_meta.compute_fabric_canonical_progress_receipt_h205f22 pr on pr.step_receipt_id=sr.receipt_id where sr.claim_id=c.claim_id and pr.canonical_roadmap_key=r.roadmap_key and pr.canonical_milestone_key is not distinct from x.canonical_milestone_key)),false) into er,eb from destruktion_meta.compute_fabric_roadmap_work_claim_h205f22 c left join destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22 x on x.roadmap_id=c.roadmap_id and x.milestone_key=c.milestone_key and x.canonical_roadmap_key=r.roadmap_key where c.state='EVIDENCE_READY' and c.roadmap_id=l2->>'roadmap_id'; select exists(select 1 from destruktion_meta.compute_fabric_canonical_progress_receipt_h205f22 pr join destruktion_meta.compute_fabric_roadmap_step_receipt_h205f22 sr on sr.receipt_id=pr.step_receipt_id join destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22 x on x.roadmap_id=sr.roadmap_id and x.milestone_key=sr.milestone_key and x.canonical_roadmap_key=r.roadmap_key where pr.canonical_roadmap_key=r.roadmap_key and pr.canonical_milestone_key is distinct from x.canonical_milestone_key) into pb; with s as(select cm.ordinal,cm.canonical_milestone_key,cm.title,case when count(x.milestone_key)=0 then 'NO_LEVEL2_MAPPING' when bool_and(m.status='VERIFIED') then 'VERIFIED' when bool_or(m.status='EVIDENCE_READY') then 'EVIDENCE_READY' when bool_or(m.status='IN_PROGRESS') then 'IN_PROGRESS' when bool_or(m.status='VERIFIED') then 'PARTIAL' when bool_or(m.status='BLOCKED') then 'BLOCKED' else 'PLANNED' end state from destruktion_meta.compute_fabric_canonical_milestone_h205f22 cm left join destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22 x on x.canonical_roadmap_key=cm.roadmap_key and x.canonical_milestone_key=cm.canonical_milestone_key and x.roadmap_id=l2->>'roadmap_id' left join destruktion_meta.compute_fabric_roadmap_milestone_h205f22 m on m.roadmap_id=x.roadmap_id and m.milestone_key=x.milestone_key where cm.roadmap_key=r.roadmap_key group by cm.ordinal,cm.canonical_milestone_key,cm.title) select jsonb_agg(jsonb_build_object('ordinal',ordinal,'canonical_milestone_key',canonical_milestone_key,'title',title,'progress_state',state) order by ordinal) into spine from s; with s as(select cm.ordinal,cm.canonical_milestone_key,case when count(x.milestone_key)=0 then 'NO_LEVEL2_MAPPING' when bool_and(m.status='VERIFIED') then 'VERIFIED' when bool_or(m.status='EVIDENCE_READY') then 'EVIDENCE_READY' when bool_or(m.status='IN_PROGRESS') then 'IN_PROGRESS' when bool_or(m.status='VERIFIED') then 'PARTIAL' when bool_or(m.status='BLOCKED') then 'BLOCKED' else 'PLANNED' end state from destruktion_meta.compute_fabric_canonical_milestone_h205f22 cm left join destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22 x on x.canonical_roadmap_key=cm.roadmap_key and x.canonical_milestone_key=cm.canonical_milestone_key and x.roadmap_id=l2->>'roadmap_id' left join destruktion_meta.compute_fabric_roadmap_milestone_h205f22 m on m.roadmap_id=x.roadmap_id and m.milestone_key=x.milestone_key where cm.roadmap_key=r.roadmap_key group by cm.ordinal,cm.canonical_milestone_key) select jsonb_build_object('foundation',(select jsonb_build_object('canonical_milestone_key','R1','progress_state',state) from s where canonical_milestone_key='R1'),'execution',(select jsonb_build_object('canonical_milestone_key',canonical_milestone_key,'progress_state',state) from s where canonical_milestone_key~'^C[0-9]+$' and state<>'VERIFIED' order by ordinal limit 1),'parallel_federation',(select jsonb_build_object('canonical_milestone_key','F1+','progress_state',state) from s where canonical_milestone_key='F1+')) into focus; if not ci then reasons:=array_append(reasons,'CANONICAL_INTEGRITY_FAILED'); end if; if not li then reasons:=array_append(reasons,'LEVEL2_DEFINITION_INTEGRITY_FAILED'); end if; if jsonb_array_length(u)>0 then reasons:=array_append(reasons,'UNMAPPED_LEVEL2_MILESTONE'); end if; if jsonb_array_length(inv)>0 then reasons:=array_append(reasons,'INVALID_MAPPING'); end if; if ab then reasons:=array_append(reasons,'ACTIVE_CLAIM_UNMAPPED'); end if; if eb then reasons:=array_append(reasons,'EVIDENCE_READY_WITHOUT_CANONICAL_PROGRESS_RECEIPT'); end if; if pb then reasons:=array_append(reasons,'CANONICAL_PROGRESS_MAPPING_MISMATCH'); end if; return jsonb_build_object('schema','metaengine.compute.roadmap-alignment.h205f22.v1','canonical_roadmap',jsonb_build_object('roadmap_key',r.roadmap_key,'version',r.version,'title',r.title,'sealed',r.sealed,'source_git_repository',r.source_git_repository,'source_git_path',r.source_git_path,'source_git_commit',r.source_git_commit),'canonical_digest',d,'canonical_integrity',ci,'git_source',jsonb_build_object('repository',r.source_git_repository,'path',r.source_git_path,'commit',r.source_git_commit),'level2_roadmap',l2->>'roadmap_id','level2_definition_integrity',li,'mapped_milestones',(select count(*) from destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22 where roadmap_id=l2->>'roadmap_id' and canonical_roadmap_key=r.roadmap_key),'unmapped_level2_milestones',u,'invalid_mappings',inv,'active_claim_alignment',ac,'evidence_ready_alignment',er,'current_canonical_focus',focus,'critical_spine_status',coalesce(spine,'[]'),'drift_detected',(cardinality(reasons)>0),'drift_reasons',to_jsonb(reasons)); end $f$;

update destruktion_meta.compute_fabric_canonical_milestone_h205f22 set sealed=true where roadmap_key='compute-fabric-canonical-roadmap-v1';
update destruktion_meta.compute_fabric_canonical_roadmap_release_h205f22 set canonical_digest=destruktion_meta.compute_fabric_canonical_roadmap_digest_h205f22(roadmap_key),sealed=true where roadmap_key='compute-fabric-canonical-roadmap-v1';

insert into destruktion_meta.compute_fabric_canonical_progress_receipt_h205f22(step_receipt_id,canonical_roadmap_key,canonical_milestone_key,canonical_acceptance_criterion,canonical_progress_summary,real_compute_effect,control_plane_only,control_plane_justification,evidence)
select sr.receipt_id,x.canonical_roadmap_key,x.canonical_milestone_key,coalesce(x.acceptance_bridge->>'criterion','mapped historical contribution'),'Historical Level-2 receipt imported for Level-1 traceability; this bridge does not independently verify the canonical milestone.',x.required_contribution,case when sr.evidence->'live'='true'::jsonb then false else true end,case when sr.evidence->'live'='true'::jsonb then null else 'Historical pre-Level-1 receipt; provenance only, not real-compute acceptance by itself.' end,sr.evidence from destruktion_meta.compute_fabric_roadmap_step_receipt_h205f22 sr join destruktion_meta.compute_fabric_level2_canonical_mapping_h205f22 x on x.roadmap_id=sr.roadmap_id and x.milestone_key=sr.milestone_key and x.canonical_roadmap_key='compute-fabric-canonical-roadmap-v1' where x.canonical_milestone_key is not null on conflict(step_receipt_id) do nothing;

create or replace function destruktion_meta.compute_fabric_claim_roadmap_work_h205f22(p_milestone_key text,p_holder_id text,p_ttl_minutes integer default 90) returns jsonb language plpgsql set search_path='pg_catalog','destruktion_meta','extensions' as $f$ declare rid text; m destruktion_meta.compute_fabric_roadmap_milestone_h205f22%rowtype; cl destruktion_meta.compute_fabric_roadmap_work_claim_h205f22%rowtype; h record; s record; sd record; gate jsonb; l2 jsonb; begin if p_ttl_minutes<15 or p_ttl_minutes>720 then raise exception 'ttl must be between 15 and 720 minutes'; end if; select roadmap_id into rid from destruktion_meta.compute_fabric_roadmap_release_h205f22 where is_current order by version desc limit 1; if rid is null then raise exception 'no current roadmap'; end if; l2:=destruktion_meta.compute_fabric_roadmap_status_h205f22(); if not coalesce((l2->>'definition_integrity')::boolean,false) then raise exception 'Level-2 roadmap definition integrity failed'; end if; gate:=destruktion_meta.compute_fabric_canonical_claim_gate_h205f22(rid,p_milestone_key); if not coalesce((gate->>'allowed')::boolean,false) then raise exception 'canonical roadmap claim gate rejected milestone %: %',p_milestone_key,gate->>'reason'; end if; update destruktion_meta.compute_fabric_roadmap_work_claim_h205f22 set state='EXPIRED' where roadmap_id=rid and state='ACTIVE' and expires_at<=now(); update destruktion_meta.compute_fabric_roadmap_milestone_h205f22 mm set status='PLANNED',updated_at=now() where mm.roadmap_id=rid and mm.status='IN_PROGRESS' and not exists(select 1 from destruktion_meta.compute_fabric_roadmap_work_claim_h205f22 c where c.roadmap_id=mm.roadmap_id and c.milestone_key=mm.milestone_key and c.state='ACTIVE' and c.expires_at>now()); select * into m from destruktion_meta.compute_fabric_roadmap_milestone_h205f22 where roadmap_id=rid and milestone_key=p_milestone_key for update; if not found then raise exception 'unknown milestone %',p_milestone_key; end if; if m.status in('VERIFIED','EVIDENCE_READY','DEFERRED') then raise exception 'milestone % is not claimable in status %',p_milestone_key,m.status; end if; if exists(select 1 from destruktion_meta.compute_fabric_roadmap_dependency_h205f22 d join destruktion_meta.compute_fabric_roadmap_milestone_h205f22 req on req.roadmap_id=d.roadmap_id and req.milestone_key=d.requires_milestone_key where d.roadmap_id=rid and d.milestone_key=p_milestone_key and d.dependency_kind='HARD' and req.status<>'VERIFIED') then raise exception 'milestone % has unsatisfied hard dependencies',p_milestone_key; end if; select supervisor_key,holder_id,mode into s from destruktion_meta.compute_fabric_supervisor_control_h205f22 where supervisor_key='COMPUTE_FABRIC_MAINLINE' and roadmap_id=rid and mode='ACTIVE'; if found then select directive_kind,target_holder_id,instructions into sd from destruktion_meta.compute_fabric_supervisor_directive_h205f22 where roadmap_id=rid and milestone_key=p_milestone_key and status='ACTIVE' and(expires_at is null or expires_at>now()) order by directive_id desc limit 1; if not found then raise exception 'milestone % is not opened by the active supervisor',p_milestone_key; end if; if sd.directive_kind not in('OPEN','CONTINUE','REASSIGN') then raise exception 'supervisor directive % blocks claim for milestone %',sd.directive_kind,p_milestone_key; end if; if sd.target_holder_id is not null and sd.target_holder_id<>p_holder_id then raise exception 'milestone % is assigned to holder %',p_milestone_key,sd.target_holder_id; end if; end if; if m.execution_class in('SERIAL_MAINLINE','MERGE_GATE') and exists(select 1 from destruktion_meta.compute_fabric_roadmap_work_claim_h205f22 c where c.roadmap_id=rid and c.state='ACTIVE' and c.expires_at>now()) then raise exception 'serial/merge milestone requires exclusive roadmap lease'; end if; if exists(select 1 from destruktion_meta.compute_fabric_roadmap_work_claim_h205f22 c join destruktion_meta.compute_fabric_roadmap_milestone_h205f22 am on am.roadmap_id=c.roadmap_id and am.milestone_key=c.milestone_key where c.roadmap_id=rid and c.state='ACTIVE' and c.expires_at>now() and(am.execution_class in('SERIAL_MAINLINE','MERGE_GATE') or m.mutation_domains&&am.mutation_domains)) then raise exception 'active work claim conflicts with milestone mutation domains'; end if; select checkpoint_id,payload_root_sha256 into h from destruktion_meta.chat_capsule_checkpoint order by created_at desc limit 1; insert into destruktion_meta.compute_fabric_roadmap_work_claim_h205f22(roadmap_id,milestone_key,holder_id,base_checkpoint_id,base_payload_root_sha256,expires_at) values(rid,p_milestone_key,p_holder_id,h.checkpoint_id,h.payload_root_sha256,now()+make_interval(mins=>p_ttl_minutes)) returning * into cl; update destruktion_meta.compute_fabric_roadmap_milestone_h205f22 set status='IN_PROGRESS',updated_at=now() where roadmap_id=rid and milestone_key=p_milestone_key; return jsonb_build_object('claim_id',cl.claim_id,'claim_token',cl.claim_token,'roadmap_id',rid,'milestone_key',p_milestone_key,'holder_id',p_holder_id,'base_checkpoint_id',h.checkpoint_id,'base_payload_root_sha256',h.payload_root_sha256,'expires_at',cl.expires_at,'mutation_domains',m.mutation_domains,'execution_class',m.execution_class,'canonical_gate',gate,'required_finish_fields',jsonb_build_array('canonical_milestone_key','canonical_acceptance_criterion','canonical_progress_summary','canonical_real_compute_effect','canonical_control_plane_only'),'supervisor_directive',case when sd is null then '{}'::jsonb else jsonb_build_object('directive_kind',sd.directive_kind,'target_holder_id',sd.target_holder_id,'instructions',sd.instructions) end); end $f$;

create or replace function destruktion_meta.compute_fabric_finish_roadmap_claim_h205f22(p_claim_id bigint,p_claim_token uuid,p_summary jsonb,p_evidence jsonb,p_research jsonb default '{}'::jsonb) returns jsonb language plpgsql set search_path='pg_catalog','destruktion_meta','extensions' as $f$ declare c destruktion_meta.compute_fabric_roadmap_work_claim_h205f22%rowtype; rid bigint; prid bigint; gate jsonb; expected text; control boolean:=false; begin select * into c from destruktion_meta.compute_fabric_roadmap_work_claim_h205f22 where claim_id=p_claim_id and claim_token=p_claim_token for update; if not found or c.state<>'ACTIVE' or c.expires_at<=now() then raise exception 'claim is not active'; end if; if not coalesce((destruktion_meta.compute_fabric_roadmap_status_h205f22()->>'definition_integrity')::boolean,false) then raise exception 'Level-2 roadmap definition integrity failed'; end if; gate:=destruktion_meta.compute_fabric_canonical_claim_gate_h205f22(c.roadmap_id,c.milestone_key); if not coalesce((gate->>'allowed')::boolean,false) then raise exception 'canonical roadmap finish gate rejected milestone %: %',c.milestone_key,gate->>'reason'; end if; expected:=case when gate->>'mapping_kind'='CROSS_CUTTING' then 'CROSS-CUTTING' else gate->>'canonical_milestone_key' end; if coalesce(p_summary->>'canonical_milestone_key','')<>coalesce(expected,'') then raise exception 'canonical_milestone_key must equal %',expected; end if; if nullif(btrim(coalesce(p_summary->>'canonical_acceptance_criterion','')),'') is null then raise exception 'canonical_acceptance_criterion is required'; end if; if nullif(btrim(coalesce(p_summary->>'canonical_progress_summary','')),'') is null then raise exception 'canonical_progress_summary is required'; end if; if nullif(btrim(coalesce(p_summary->>'canonical_real_compute_effect','')),'') is null then raise exception 'canonical_real_compute_effect is required'; end if; if p_summary?'canonical_control_plane_only' and jsonb_typeof(p_summary->'canonical_control_plane_only')<>'boolean' then raise exception 'canonical_control_plane_only must be boolean'; end if; control:=coalesce((p_summary->>'canonical_control_plane_only')::boolean,false); if control and nullif(btrim(coalesce(p_summary->>'canonical_control_plane_justification','')),'') is null then raise exception 'control-plane-only progress requires canonical_control_plane_justification'; end if; insert into destruktion_meta.compute_fabric_roadmap_step_receipt_h205f22(roadmap_id,milestone_key,claim_id,step_kind,status,base_checkpoint_id,summary,evidence,research) values(c.roadmap_id,c.milestone_key,c.claim_id,'WORKSTREAM_COMPLETION','EVIDENCE_READY',c.base_checkpoint_id,coalesce(p_summary,'{}'),coalesce(p_evidence,'{}'),coalesce(p_research,'{}')) returning receipt_id into rid; insert into destruktion_meta.compute_fabric_canonical_progress_receipt_h205f22(step_receipt_id,canonical_roadmap_key,canonical_milestone_key,canonical_acceptance_criterion,canonical_progress_summary,real_compute_effect,control_plane_only,control_plane_justification,evidence) values(rid,gate->>'canonical_roadmap_key',nullif(gate->>'canonical_milestone_key',''),p_summary->>'canonical_acceptance_criterion',p_summary->>'canonical_progress_summary',p_summary->>'canonical_real_compute_effect',control,p_summary->>'canonical_control_plane_justification',coalesce(p_evidence,'{}')) returning canonical_progress_receipt_id into prid; update destruktion_meta.compute_fabric_roadmap_work_claim_h205f22 set state='EVIDENCE_READY',heartbeat_at=now(),work_summary=coalesce(p_summary,'{}'),evidence=coalesce(p_evidence,'{}') where claim_id=p_claim_id; update destruktion_meta.compute_fabric_roadmap_milestone_h205f22 set status='EVIDENCE_READY',updated_at=now() where roadmap_id=c.roadmap_id and milestone_key=c.milestone_key; return jsonb_build_object('receipt_id',rid,'canonical_progress_receipt_id',prid,'roadmap_id',c.roadmap_id,'milestone_key',c.milestone_key,'canonical_roadmap_key',gate->>'canonical_roadma